import fs from "node:fs";
import path from "node:path";
import YAML from "yaml";

export const OPENAPI_ZOD_GENERATED_COMMENT =
  "// SPDX-License-Identifier: GPL-3.0-only\n// This file is generated by tools/contracts/generate-openapi-contracts.mjs.";

const OPENAPI_METHODS = new Set(["get", "post", "put", "patch", "delete"]);
const RUNTIME_SCHEMA_ANNOTATIONS = [
  "x-zinuto-runtime-request-schema",
  "x-zinuto-runtime-response-schema",
];

const quote = (value) => JSON.stringify(value);

const indent = (text, spaces = 2) => {
  const pad = " ".repeat(spaces);
  return text
    .split("\n")
    .map((line) => (line ? `${pad}${line}` : line))
    .join("\n");
};

const unique = (values) => [...new Set(values)];

const lowerFirst = (value) => value.charAt(0).toLowerCase() + value.slice(1);

const upperFirst = (value) => value.charAt(0).toUpperCase() + value.slice(1);

const componentFromRef = (ref) => {
  const prefix = "#/components/schemas/";
  if (!String(ref).startsWith(prefix)) {
    throw new Error(`[openapi-zod] unsupported $ref outside components.schemas: ${ref}`);
  }
  return String(ref).slice(prefix.length);
};

const schemaSourceName = (schema) =>
  String(schema?.["x-zinuto-zod-source"] ?? "openapi");

const schemaImportTarget = ({ schema, componentName }) => {
  const target = schema?.["x-zinuto-zod-import"];
  if (!target || typeof target !== "object" || Array.isArray(target)) {
    throw new Error(
      `[openapi-zod] #/components/schemas/${componentName} external schema is missing x-zinuto-zod-import.`,
    );
  }
  const modulePath = target.module;
  const importName = target.name;
  if (typeof modulePath !== "string" || !modulePath) {
    throw new Error(
      `[openapi-zod] #/components/schemas/${componentName} external schema import is missing module.`,
    );
  }
  if (typeof importName !== "string" || !importName) {
    throw new Error(
      `[openapi-zod] #/components/schemas/${componentName} external schema import is missing name.`,
    );
  }
  return { modulePath, importName };
};

const allowsAdditionalProperties = (schema) =>
  schema?.["x-zinuto-zod-allow-additional-properties"] === true;

export const readOpenApiDocument = (filePath) => {
  const sourceText = fs.readFileSync(filePath, "utf8");
  const document = YAML.parseDocument(sourceText, {
    prettyErrors: true,
    strict: true,
  });
  if (document.errors.length) {
    throw new Error(
      [
        `[openapi-zod] ${path.relative(process.cwd(), filePath)} is not parseable YAML:`,
        ...document.errors.map((error) => `- ${error.message}`),
      ].join("\n"),
    );
  }
  return {
    sourceText,
    spec: document.toJSON(),
  };
};

export const collectRuntimeSchemaNames = (spec) => {
  const names = [];
  for (const pathItem of Object.values(spec.paths ?? {})) {
    for (const [method, operation] of Object.entries(pathItem ?? {})) {
      if (!OPENAPI_METHODS.has(method)) {
        continue;
      }
      for (const annotation of RUNTIME_SCHEMA_ANNOTATIONS) {
        const schemaName = operation?.[annotation];
        if (schemaName) {
          names.push(String(schemaName));
        }
      }
    }
  }
  return unique(names).sort();
};

const defaultExportNamesForComponent = ({ componentName, serviceName }) => {
  const names = [lowerFirst(componentName) + "Schema"];
  if (serviceName === "desktop-local-api") {
    if (!/^Desktop/u.test(componentName)) {
      names.push(`desktop${componentName}Schema`);
    }
  }
  return unique(names);
};

const exportNamesForComponent = ({ componentName, schema, serviceName }) => {
  const explicit = schema?.["x-zinuto-zod-export-name"];
  if (explicit) {
    return [String(explicit)];
  }
  return defaultExportNamesForComponent({ componentName, serviceName });
};

export const componentConstName = ({ componentName, serviceName }) => {
  void serviceName;
  return `desktopOpenApi${componentName}Schema`;
};

const assertObject = (schema, label) => {
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
    throw new Error(`[openapi-zod] ${label} must be an object schema.`);
  }
};

const formatChain = (base, calls) => calls.reduce((value, call) => `${value}.${call}`, base);

const zodLiteral = (value) => `z.literal(${quote(value)})`;

const zodEnum = (values) => {
  if (values.length === 0) {
    throw new Error("[openapi-zod] enum must contain at least one value.");
  }
  if (values.every((value) => typeof value === "string")) {
    return `z.enum([${values.map(quote).join(", ")}])`;
  }
  if (values.length === 1) {
    return zodLiteral(values[0]);
  }
  return `z.union([${values.map(zodLiteral).join(", ")}])`;
};

const normalizeTypeList = (schema) => {
  if (Array.isArray(schema.type)) {
    return schema.type.map(String);
  }
  return schema.type ? [String(schema.type)] : [];
};

export class OpenApiZodBuilder {
  constructor({ components, serviceName }) {
    this.components = components;
    this.serviceName = serviceName;
    this.generatedComponents = new Set();
    this.failures = [];
  }

  buildComponentExpression(componentName) {
    const schema = this.components[componentName];
    if (!schema) {
      throw new Error(`[openapi-zod] missing component schema: ${componentName}`);
    }
    this.generatedComponents.add(componentName);
    return this.buildSchemaExpression(schema, `#/components/schemas/${componentName}`);
  }

  buildSchemaExpression(schema, label) {
    assertObject(schema, label);
    const source = schemaSourceName(schema);
    if (source !== "openapi") {
      throw new Error(`[openapi-zod] ${label} is ${source}; it cannot be generated from OpenAPI fields.`);
    }
    const nullable = schema.nullable === true || normalizeTypeList(schema).includes("null");
    const expression = this.buildNonNullableSchemaExpression(schema, label);
    const nullableExpression = nullable ? `${expression}.nullable()` : expression;
    return Object.prototype.hasOwnProperty.call(schema, "default")
      ? `${nullableExpression}.default(${quote(schema.default)})`
      : nullableExpression;
  }

  buildNonNullableSchemaExpression(schema, label) {
    if (schema.$ref) {
      const componentName = componentFromRef(schema.$ref);
      this.generatedComponents.add(componentName);
      return `z.lazy(() => ${componentConstName({
        componentName,
        serviceName: this.serviceName,
      })})`;
    }
    if (Object.prototype.hasOwnProperty.call(schema, "const")) {
      return zodLiteral(schema.const);
    }
    if (Array.isArray(schema.enum)) {
      return zodEnum(schema.enum.filter((value) => value !== null));
    }
    if (Array.isArray(schema.oneOf)) {
      return this.buildUnionExpression(schema.oneOf, `${label}.oneOf`);
    }
    if (Array.isArray(schema.anyOf)) {
      return this.buildUnionExpression(schema.anyOf, `${label}.anyOf`);
    }
    if (Array.isArray(schema.allOf)) {
      return this.buildIntersectionExpression(schema.allOf, `${label}.allOf`);
    }

    const types = normalizeTypeList(schema).filter((type) => type !== "null");
    if (types.length > 1) {
      return this.buildUnionExpression(
        types.map((type) => ({ ...schema, type, nullable: false })),
        `${label}.type`,
      );
    }
    const type = types[0];
    switch (type) {
      case "string":
        return this.buildStringExpression(schema);
      case "integer":
      case "number":
        return this.buildNumberExpression(schema, type);
      case "boolean":
        return "z.boolean()";
      case "array":
        return this.buildArrayExpression(schema, label);
      case "object":
        return this.buildObjectExpression(schema, label);
      default:
        if (schema.properties || schema.additionalProperties !== undefined) {
          return this.buildObjectExpression({ ...schema, type: "object" }, label);
        }
        throw new Error(`[openapi-zod] ${label} is missing a supported type or composition.`);
    }
  }

  buildUnionExpression(items, label) {
    if (items.length === 0) {
      throw new Error(`[openapi-zod] ${label} must contain at least one branch.`);
    }
    const expressions = items.map((item, index) =>
      this.buildSchemaExpression(item, `${label}[${index}]`),
    );
    return expressions.length === 1
      ? expressions[0]
      : `z.union([${expressions.join(", ")}])`;
  }

  buildIntersectionExpression(items, label) {
    if (items.length === 0) {
      throw new Error(`[openapi-zod] ${label} must contain at least one branch.`);
    }
    return items
      .map((item, index) => this.buildSchemaExpression(item, `${label}[${index}]`))
      .reduce((expression, next) => `${expression}.and(${next})`);
  }

  buildStringExpression(schema) {
    const calls = [];
    if (schema.minLength !== undefined) {
      calls.push(`min(${Number(schema.minLength)})`);
    }
    if (schema.maxLength !== undefined) {
      calls.push(`max(${Number(schema.maxLength)})`);
    }
    if (schema.pattern) {
      calls.push(`regex(new RegExp(${quote(String(schema.pattern))}))`);
    }
    if (schema.format === "date-time") {
      calls.push("datetime({ offset: true })");
    } else if (schema.format === "uuid") {
      calls.push("uuid()");
    } else if (schema.format === "uri") {
      calls.push("url()");
    }
    return formatChain("z.string()", calls);
  }

  buildNumberExpression(schema, type) {
    const calls = [];
    if (type === "integer") {
      calls.push("int()");
    }
    if (schema.minimum !== undefined) {
      calls.push(`min(${Number(schema.minimum)})`);
    }
    if (schema.maximum !== undefined) {
      calls.push(`max(${Number(schema.maximum)})`);
    }
    if (schema.exclusiveMinimum !== undefined) {
      calls.push(`gt(${Number(schema.exclusiveMinimum)})`);
    }
    if (schema.exclusiveMaximum !== undefined) {
      calls.push(`lt(${Number(schema.exclusiveMaximum)})`);
    }
    return formatChain("z.number()", calls);
  }

  buildArrayExpression(schema, label) {
    if (!schema.items) {
      throw new Error(`[openapi-zod] ${label} array is missing items.`);
    }
    const itemExpression = this.buildSchemaExpression(schema.items, `${label}.items`);
    const calls = [];
    if (schema.minItems !== undefined) {
      calls.push(`min(${Number(schema.minItems)})`);
    }
    if (schema.maxItems !== undefined) {
      calls.push(`max(${Number(schema.maxItems)})`);
    }
    if (schema.uniqueItems === true) {
      calls.push(
        'refine((items) => new Set(items.map((item) => JSON.stringify(item))).size === items.length, { message: "uniqueItems" })',
      );
    }
    return formatChain(`z.array(${itemExpression})`, calls);
  }

  buildObjectExpression(schema, label) {
    const properties = schema.properties ?? {};
    const required = new Set(schema.required ?? []);
    const entries = Object.entries(properties);
    let base;
    if (entries.length) {
      const body = entries
        .map(([key, propertySchema]) => {
          const propertyExpression = this.buildSchemaExpression(
            propertySchema,
            `${label}.properties.${key}`,
          );
          const optionalSuffix =
            required.has(key) ||
            Object.prototype.hasOwnProperty.call(propertySchema, "default")
              ? ""
              : ".optional()";
          return `${quote(key)}: ${propertyExpression}${optionalSuffix},`;
        })
        .join("\n");
      base = `z.object({\n${indent(body, 2)}\n})`;
    } else if (schema.additionalProperties === false) {
      base = "z.object({})";
    } else if (schema.additionalProperties === true) {
      if (!allowsAdditionalProperties(schema)) {
        throw new Error(
          `[openapi-zod] ${label} uses additionalProperties: true without x-zinuto-zod-allow-additional-properties.`,
        );
      }
      return "z.record(z.string(), z.unknown())";
    } else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
      const valueExpression = this.buildSchemaExpression(
        schema.additionalProperties,
        `${label}.additionalProperties`,
      );
      return `z.record(z.string(), ${valueExpression})`;
    } else {
      throw new Error(
        `[openapi-zod] ${label} object has no properties or explicit additionalProperties marker.`,
      );
    }

    if (schema.additionalProperties === false) {
      return `${base}.strict()`;
    }
    if (schema.additionalProperties === true) {
      if (!allowsAdditionalProperties(schema)) {
        throw new Error(
          `[openapi-zod] ${label} uses additionalProperties: true without x-zinuto-zod-allow-additional-properties.`,
        );
      }
      return `${base}.passthrough()`;
    }
    if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
      throw new Error(
        `[openapi-zod] ${label} mixes fixed properties with schema-valued additionalProperties; split it into a named map component.`,
      );
    }
    return `${base}.passthrough()`;
  }
}

const buildComponentExportMap = ({ components, serviceName }) => {
  const byExportName = new Map();
  for (const [componentName, schema] of Object.entries(components)) {
    for (const exportName of exportNamesForComponent({
      componentName,
      schema,
      serviceName,
    })) {
      if (!byExportName.has(exportName)) {
        byExportName.set(exportName, componentName);
      }
    }
  }
  return byExportName;
};

const collectGeneratedComponentClosure = ({ builder, rootComponents }) => {
  const queue = [...rootComponents];
  const generated = [];
  const seen = new Set();
  while (queue.length) {
    const componentName = queue.shift();
    if (seen.has(componentName)) {
      continue;
    }
    seen.add(componentName);
    const before = new Set(builder.generatedComponents);
    const expression = builder.buildComponentExpression(componentName);
    generated.push({ componentName, expression });
    for (const dependency of builder.generatedComponents) {
      if (!before.has(dependency) && !seen.has(dependency)) {
        queue.push(dependency);
      }
    }
  }
  return generated;
};

const buildImportBlock = (importsByModule) => {
  const blocks = [];
  for (const [modulePath, names] of [...importsByModule.entries()].sort()) {
    blocks.push(`import {\n${indent(unique(names).sort().join(",\n"), 2)},\n} from ${quote(modulePath)};`);
  }
  return blocks.join("\n");
};

export const buildOpenApiZodModule = ({ spec, serviceName }) => {
  const components = spec.components?.schemas ?? {};
  const runtimeSchemaNames = collectRuntimeSchemaNames(spec);
  const componentByExportName = buildComponentExportMap({ components, serviceName });
  const componentBindings = [];
  const externalBindings = [];
  const rootComponents = new Set();

  for (const schemaName of runtimeSchemaNames) {
    const componentName = componentByExportName.get(schemaName);
    if (!componentName) {
      throw new Error(
        `[openapi-zod] runtime schema ${schemaName} has no matching components.schemas entry.`,
      );
    }
    const schema = components[componentName];
    const source = schemaSourceName(schema);
    if (source === "openapi") {
      componentBindings.push({ schemaName, componentName });
      rootComponents.add(componentName);
      continue;
    }
    if (source === "external") {
      const importTarget = schemaImportTarget({ schema, componentName });
      if (importTarget.importName !== schemaName) {
        throw new Error(
          `[openapi-zod] #/components/schemas/${componentName} external import name ${importTarget.importName} must match runtime export ${schemaName}.`,
        );
      }
      externalBindings.push({
        schemaName,
        componentName,
        modulePath: importTarget.modulePath,
      });
      continue;
    }
    throw new Error(
      `[openapi-zod] #/components/schemas/${componentName} has unsupported x-zinuto-zod-source: ${source}.`,
    );
  }

  const builder = new OpenApiZodBuilder({ components, serviceName });
  const generatedComponents = collectGeneratedComponentClosure({
    builder,
    rootComponents,
  });
  const componentConstByName = new Map(
    generatedComponents.map(({ componentName }) => [
      componentName,
      componentConstName({ componentName, serviceName }),
    ]),
  );

  const importsByModule = new Map();
  for (const binding of externalBindings) {
    const names = importsByModule.get(binding.modulePath) ?? [];
    names.push(binding.schemaName);
    importsByModule.set(binding.modulePath, names);
  }

  const prefix = "DESKTOP";
  const componentDeclarations = generatedComponents
    .map(
      ({ componentName, expression }) =>
        `const ${componentConstByName.get(componentName)} = ${expression};`,
    )
    .join("\n\n");
  const componentMapEntries = generatedComponents
    .map(
      ({ componentName }) =>
        `  ${quote(componentName)}: ${componentConstByName.get(componentName)},`,
    )
    .join("\n");
  const runtimeEntries = [
    ...componentBindings.map(
      ({ schemaName, componentName }) =>
        `  ${quote(schemaName)}: { source: "component", component: ${quote(componentName)}, schema: ${componentConstByName.get(componentName)} },`,
    ),
    ...externalBindings.map(
      ({ schemaName, componentName }) =>
        `  ${quote(schemaName)}: { source: "external", component: ${quote(componentName)}, schema: ${schemaName} },`,
    ),
  ]
    .sort()
    .join("\n");

  const importBlock = buildImportBlock(importsByModule);
  return `${OPENAPI_ZOD_GENERATED_COMMENT}
// Do not edit by hand; update contracts/openapi/*.yaml and regenerate.

import { z } from "zod";
${importBlock ? `\n${importBlock}\n` : ""}
${componentDeclarations}

export const ${prefix}_OPENAPI_COMPONENT_ZOD_SCHEMAS = {
${componentMapEntries}
} as const;

export const ${prefix}_OPENAPI_RUNTIME_SCHEMA_BINDINGS = {
${runtimeEntries}
} as const;
`;
};
